+// Only used after andI_rReg_imm31 on the count, so the count is below 32 and CF is cleared
+instruct bzhiI_rReg_rReg_rReg(rRegI dst, rRegI src, rRegI count, rFlagsReg cr)
+%{
+  effect(DEF dst, USE src, USE count, KILL cr);
+  flag(PD::Flag_sets_sign_flag, PD::Flag_sets_zero_flag, PD::Flag_clears_overflow_flag, PD::Flag_clears_carry_flag);
